/* Homepage Deduções - year selector, sector/expense search, and the personal lens.
 *
 * NO RATE OR CEILING IS WRITTEN IN THIS FILE (ch.17 responsibilities). Everything numeric is read
 * from the artefacts the repository already publishes and cross-checks in CI:
 *     year_snapshots.json   what was verified, per year, with its verification state
 *     audit-manifest.json   what tool.js actually computes with, generated by make-audit.mjs
 *     audit-freshness.json  whether the article still says so
 *
 * The static table in deducoes.html stays hand-maintained ON PURPOSE. It is the third independent
 * source in test-deducoes-sync.js's three-way agreement (page == CEIL == snapshots); generating it
 * from the manifest would turn the cross-check into a comparison of a file with its own derivative
 * and quietly retire the invariant. It is also the no-JS fallback.
 */
(function () {
  "use strict";

  var form = document.getElementById("ded-form");
  if (!form) return;

  var ano = document.getElementById("db-ano");
  var q = document.getElementById("db-q");
  var out = document.getElementById("db-result");
  var list = document.getElementById("db-res-list");
  var resTitle = document.getElementById("db-res-title");
  var heroAno = document.getElementById("hero-ano");
  var lensGeral = document.getElementById("lens-geral");
  var lensMeu = document.getElementById("lens-meu");
  var lensNote = document.getElementById("lens-note");
  var locked = document.getElementById("personal-locked");
  var view = document.getElementById("personal-view");

  var DATA = null;

  function esc(s) {
    return String(s == null ? "" : s).replace(/[<>&"]/g, function (c) {
      return { "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;" }[c];
    });
  }

  function load() {
    if (DATA) return Promise.resolve(DATA);
    return Promise.all([
      fetch("/year_snapshots.json").then(function (r) { return r.json(); }),
      fetch("/audit-manifest.json", { cache: "no-store" }).then(function (r) { return r.json(); }).catch(function () { return null; }),
      fetch("/audit-freshness.json", { cache: "no-store" }).then(function (r) { return r.json(); }).catch(function () { return null; })
    ]).then(function (a) {
      DATA = { snap: a[0], audit: a[1], fresh: a[2] };
      return DATA;
    });
  }

  /* DED-001: offer only years that actually exist in the snapshots. A year with no data must not
     appear in the list at all - an empty year would render as "0 EUR deducted", which is the
     "absence is not zero" mistake this whole vocabulary exists to prevent. */
  load().then(function (d) {
    var years = Object.keys(d.snap.years || {}).sort().reverse();
    if (!years.length) return;
    ano.innerHTML = years.map(function (y) {
      return '<option value="' + esc(y) + '">' + esc(y) + "</option>";
    }).join("");
    // keep the newest year selected, and mirror it into the hero eyebrow + chapter 01 heading
    ano.value = years[0];
    syncYear();
  }).catch(function () { /* selects keep their static default; the table below is unaffected */ });

  function syncYear() {
    var y = ano.value;
    if (heroAno) heroAno.textContent = y;
    Array.prototype.forEach.call(document.querySelectorAll(".ano-inline"), function (el) {
      el.textContent = y;
    });
  }
  ano.addEventListener("change", function () { syncYear(); });

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var term = q.value.trim().toLowerCase();
    load().then(function (d) {
      var rows = (d.audit && d.audit.rows) || [];
      var fmap = {};
      if (d.fresh && d.fresh.sources) d.fresh.sources.forEach(function (s) { fmap[s.id] = s.status; });

      var hits = rows.filter(function (r) {
        if (!term) return true;
        return ((r.sector || "") + " " + (r.code || "") + " " + (r.article || "")).toLowerCase()
          .indexOf(term) !== -1;
      });

      out.hidden = false;
      if (!hits.length) {
        list.innerHTML = '<p class="note"><svg aria-hidden="true" focusable="false">' +
          '<use href="/assets/icons.svg#fb-info"></use></svg><span>Sem correspondencia. ' +
          'Ve a tabela completa abaixo ou abre a <a href="/auditoria">matriz gerada</a>.</span></p>';
      } else {
        list.innerHTML = hits.map(function (r) {
          var st = fmap[r.source_id];
          var conf = st === "OK"
            ? '<span class="state state-ok"><svg aria-hidden="true" focusable="false">' +
              '<use href="/assets/icons.svg#fb-check"></use></svg>Conferido na fonte</span>'
            : '<span class="state state-unknown"><svg aria-hidden="true" focusable="false">' +
              '<use href="/assets/icons.svg#fb-circulo"></use></svg>Por confirmar</span>';
          return '<article class="db-hit"><h4>' + esc(r.code) + " &middot; " + esc(r.sector) + "</h4>" +
            '<p class="db-meta">' +
              '<span class="num">' + esc(r.rate) + " " + esc(r.base) + "</span>" +
              (r.ceiling_eur != null ? '<span class="num">teto ' + esc(r.ceiling_eur) + " &euro;</span>" : "") +
              (r.article ? '<span class="mono">' + esc(r.article) + "</span>" : "") +
              conf +
            "</p>" +
            (r.source_url ? '<p><a href="' + esc(r.source_url) + '" target="_blank" rel="noopener">Abrir a fonte oficial</a></p>' : "") +
            "</article>";
        }).join("");
      }
      resTitle.focus();
    });
  });

  /* ---------------------------------------------------------------- the personal lens
   * Reads ONLY what perfil.html already stored in this browser. If there is nothing, the lens
   * stays locked and says so. It never renders placeholder figures in the personal panel. */
  var PROFILE_KEYS = ["fb_profile", "efh_profile", "fb-perfil"];

  function readProfile() {
    for (var i = 0; i < PROFILE_KEYS.length; i++) {
      try {
        var raw = localStorage.getItem(PROFILE_KEYS[i]);
        if (!raw) continue;
        var o = JSON.parse(raw);
        if (!o) continue;
        if (o.expiresAt && Date.now() >= o.expiresAt) continue;   // expired = absent
        return o;
      } catch (e) { /* unreadable is the same as absent */ }
    }
    return null;
  }

  var profile = readProfile();
  if (!profile) {
    lensMeu.disabled = true;
    lensMeu.setAttribute("aria-disabled", "true");
  } else {
    lensNote.textContent = "Os teus dados estao neste navegador e expiram no fim do dia.";
  }

  function setLens(personal) {
    lensGeral.setAttribute("aria-pressed", personal ? "false" : "true");
    lensMeu.setAttribute("aria-pressed", personal ? "true" : "false");
    if (locked) locked.hidden = !!personal && !!profile;
    if (view) view.hidden = !(personal && profile);
  }

  lensGeral.addEventListener("click", function () { setLens(false); });
  lensMeu.addEventListener("click", function () {
    if (!profile) {
      // Explain, do not silently do nothing.
      lensNote.textContent = "Ainda nao ha uma situacao carregada neste navegador. Abre “A minha situacao” primeiro.";
      lensNote.classList.add("state-warn");
      return;
    }
    setLens(true);
  });
})();
